/** The layout nearest to a race's location (the source lists every circuit by its centre). */
export function circuitNear(lat: number, lng: number, maxKm = 30): CircuitShape | null {
  let best: CircuitShape | null = null;
  let bestKm = Infinity;
  for (const c of CIRCUITS) {
    const dLat = ((c.lat - lat) * Math.PI) / 180;
    const dLng = ((c.lng - lng) * Math.PI) / 180;
    const a = Math.sin(dLat / 2) ** 2 + Math.cos((lat * Math.PI) / 180) * Math.cos((c.lat * Math.PI) / 180) * Math.sin(dLng / 2) ** 2;
    const km = 12742 * Math.asin(Math.sqrt(a));
    if (km < bestKm) [best, bestKm] = [c, km];
  }
  return bestKm <= maxKm ? best : null;
}
